// Una salida por cuenta activa, con el entorno y la URL interna del backend que le corresponden.
// En staging (disparador manual) se puede limitar a un slug y mandar todo a una casilla de prueba, para no
// escribirle a todas las cuentas de staging. En producción esos dos campos se ignoran. Modo: una vez para todos.
const config = $('Entorno Staging').isExecuted ? $('Entorno Staging').first().json : $('Entorno Producción').first().json;
const entorno = config.entorno === 'dev' ? 'dev' : 'prod';
const apiBase = String(config.apiBase || '');
const destinatarioPrueba = entorno === 'dev' ? String(config.destinatarioPrueba || '').trim() : '';
const soloSlug = entorno === 'dev' ? String(config.soloSlug || '').trim() : '';

const cuentas = $input.first().json.accounts;
if (!Array.isArray(cuentas)) {
  throw new Error('La API no devolvió la lista de cuentas (falta "accounts").');
}

return cuentas
  .filter((c) => c && c.slug && (!soloSlug || c.slug === soloSlug))
  .map((c) => ({
    json: {
      entorno,
      apiBase,
      slug: String(c.slug),
      comercio: String(c.businessName || ''),
      destinatario: destinatarioPrueba || String(c.ownerEmail || ''),
    },
  }));

