// Arma el reporte semanal de márgenes con la plantilla compartida de MargenX (ADR-009): el HTML A4 que Gotenberg
// convierte a PDF y, en el envío de los lunes, el mail que lo acompaña. Un solo generador para el PDF del mail y el
// de la descarga a pedido (webhook report-pdf). No calcula nada: muestra los números del backend (ADR-003).
// Modo: una vez por ítem.
// <plantilla-mail-margenx>
// Plantilla compartida de los mails de MargenX (ingesta, alertas, invitaciones y reporte semanal) y de su versión A4.
// Fuente única: infra/n8n/plantillas/mail-margenx.js. No editar este bloque en n8n:
// se copia a los workflows con `node infra/n8n/plantillas/sincronizar.mjs`.
const MX_APP = { prod: 'https://margenx.tech', dev: 'https://dev.margenx.tech' };
const MX_TONOS = {
  peligro: { fondo: '#fef2f2', borde: '#ef4444', titulo: '#991b1b', texto: '#7f1d1d', chipFondo: '#450a0a', chipTexto: '#fca5a5', chipBorde: '#7f1d1d' },
  aviso: { fondo: '#fffbeb', borde: '#f59e0b', titulo: '#92400e', texto: '#78350f', chipFondo: '#451a03', chipTexto: '#fcd34d', chipBorde: '#78350f' },
  info: { fondo: '#eef2ff', borde: '#4f46e5', titulo: '#3730a3', texto: '#312e81', chipFondo: '#1e1b4b', chipTexto: '#c7d2fe', chipBorde: '#3730a3' },
  ok: { fondo: '#f0fdf4', borde: '#22c55e', titulo: '#166534', texto: '#14532d', chipFondo: '#052e16', chipTexto: '#86efac', chipBorde: '#14532d' },
};
function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
// Número con separador de miles argentino: 2.500
function mxEntero(n) {
  return (Number(n) || 0).toLocaleString('es-AR');
}
// "1 fila" / "2 filas": el singular solo para exactamente 1
function mxCantidad(n, singular, plural) {
  return `${mxEntero(n)} ${Number(n) === 1 ? singular : plural}`;
}
function mxPorcentaje(n) {
  return (Number(n) || 0).toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
}
function mxPesos(n) {
  return new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(n) || 0);
}
function mxBoton(href, etiqueta) {
  return `<a href="${escapeHtml(href)}" target="_blank" style="background-color: #4f46e5; color: #ffffff; padding: 10px 18px; font-size: 14px; font-weight: 700; text-decoration: none; border-radius: 6px; display: inline-block;">${escapeHtml(etiqueta)}</a>`;
}
// Bloque destacado con título, contenido (HTML ya escapado) y un botón opcional
function mxAviso(tono, titulo, contenidoHtml, boton) {
  const t = MX_TONOS[tono] || MX_TONOS.info;
  const accion = boton ? `<p style="margin: 12px 0 0 0;">${mxBoton(boton.href, boton.etiqueta)}</p>` : '';
  return `<div style="background-color: ${t.fondo}; border-left: 4px solid ${t.borde}; padding: 12px 12px; border-radius: 0 8px 8px 0; margin: 0 0 16px 0;">
  <p style="margin: 0; font-size: 15px; font-weight: 700; color: ${t.titulo};">${escapeHtml(titulo)}</p>
  <div style="margin: 6px 0 0 0; font-size: 14px; line-height: 1.5; color: ${t.texto};">${contenidoHtml}</div>${accion}
</div>`;
}
// Tabla de productos bajo su margen mínimo, con el botón "Ajustar" de cada uno
function mxTablaProductos(filas) {
  const cuerpo = filas.map((f) => `<tr style="border-bottom: 1px solid #e2e8f0;">
  <td style="padding: 10px 8px; font-size: 14px; font-weight: 600; color: #0f172a;">${escapeHtml(f.nombre)}<div style="font-size: 12px; font-weight: 400; color: #64748b;">Nuevo costo: ${escapeHtml(mxPesos(f.costo))}</div></td>
  <td style="padding: 10px 8px; font-size: 13px; text-align: right; white-space: nowrap;"><span style="background-color: #fee2e2; color: #b91c1c; font-weight: 700; padding: 3px 6px; border-radius: 4px; border: 1px solid #fecaca; display: inline-block;">${escapeHtml(mxPorcentaje(f.margen))}</span><div style="font-size: 12px; color: #475569; margin-top: 4px;">mín. ${escapeHtml(mxPorcentaje(f.minimo))}</div></td>
  <td style="padding: 10px 8px; text-align: right;"><a href="${escapeHtml(f.enlace)}" target="_blank" style="background-color: #4f46e5; color: #ffffff; padding: 6px 10px; font-size: 12px; font-weight: 600; text-decoration: none; border-radius: 4px; display: inline-block;">Ajustar</a></td>
</tr>`).join('');
  return `<table width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse: collapse; border: 1px solid #e2e8f0; width: 100%; background-color: #ffffff;">
<thead><tr style="background-color: #f1f5f9; text-align: left;">
  <th style="padding: 8px; font-size: 11px; font-weight: 700; color: #475569; text-transform: uppercase;">Producto</th>
  <th style="padding: 8px; font-size: 11px; font-weight: 700; color: #b91c1c; text-transform: uppercase; text-align: right;">Margen</th>
  <th style="padding: 8px; font-size: 11px; font-weight: 700; color: #475569; text-transform: uppercase; text-align: right;"></th>
</tr></thead>
<tbody>${cuerpo}</tbody>
</table>`;
}
// Documento completo: encabezado de marca, etiqueta de estado, contenido y pie
function mxDocumento({ titulo, etiqueta, tono, contenidoHtml, pieHtml }) {
  const t = MX_TONOS[tono] || MX_TONOS.info;
  return `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(titulo)}</title>
</head>
<body style="margin: 0; padding: 0; background-color: #f8fafc; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #0f172a;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f8fafc; padding: 16px 8px;">
    <tr>
      <td align="center">
        <table width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width: 600px; background-color: #ffffff; border-radius: 12px; overflow: hidden; border: 1px solid #e2e8f0;">
          <tr>
            <td style="background-color: #0f172a; padding: 18px 16px;">
              <table width="100%" cellpadding="0" cellspacing="0" border="0">
                <tr>
                  <td>
                    <span style="font-size: 20px; font-weight: 800; color: #ffffff; letter-spacing: 0.5px;">MARGEN<span style="color: #6366f1;">X</span></span>
                    <span style="font-size: 11px; color: #94a3b8; display: block; margin-top: 2px; text-transform: uppercase; letter-spacing: 1px;">Control de rentabilidad en tiempo real</span>
                  </td>
                  <td align="right">
                    <span style="background-color: ${t.chipFondo}; color: ${t.chipTexto}; font-size: 11px; font-weight: 700; padding: 4px 10px; border-radius: 9999px; border: 1px solid ${t.chipBorde}; text-transform: uppercase; white-space: nowrap; display: inline-block;">${escapeHtml(etiqueta)}</span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
          <tr>
            <td style="padding: 20px 16px; font-size: 14px; line-height: 1.5; color: #334155;">
              ${contenidoHtml}
            </td>
          </tr>
          <tr>
            <td style="background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 16px; text-align: center;">
              ${pieHtml ? `<p style="margin: 0 0 8px 0; font-size: 12px; color: #64748b;">${pieHtml}</p>` : ''}
              <p style="margin: 0; font-size: 11px; color: #94a3b8;">MargenX &bull; Soporte: soporte@margenx.tech</p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}
// Versión para imprimir en A4 (reporte semanal en PDF, que convierte Gotenberg): mismo encabezado de marca,
// página A4 con @page, encabezados de tabla que se repiten en cada hoja y filas que nunca se cortan.
// Las tablas usan las clases mx-num (montos alineados a la derecha), mx-nowrap (texto corto que no se parte,
// como la columna Estado) y mx-sub (segunda línea de una celda).
function mxDocumentoA4({ titulo, etiqueta, tono, contenidoHtml, pieHtml }) {
  const t = MX_TONOS[tono] || MX_TONOS.info;
  return `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(titulo)}</title>
  <style>
    @page { size: A4; margin: 14mm 12mm 16mm 12mm; }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 10.5pt; line-height: 1.45; color: #0f172a; background-color: #ffffff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .mx-marca { background-color: #0f172a; padding: 12px 16px; border-radius: 8px; display: flex; justify-content: space-between; align-items: center; }
    .mx-logo { font-size: 18pt; font-weight: 800; color: #ffffff; letter-spacing: 0.5px; }
    .mx-lema { display: block; font-size: 7.5pt; color: #94a3b8; text-transform: uppercase; letter-spacing: 1px; margin-top: 2px; }
    .mx-chip { background-color: ${t.chipFondo}; color: ${t.chipTexto}; border: 1px solid ${t.chipBorde}; font-size: 8pt; font-weight: 700; padding: 3px 10px; border-radius: 9999px; text-transform: uppercase; white-space: nowrap; }
    h1 { font-size: 17pt; margin: 16px 0 2px 0; }
    h2 { font-size: 13pt; margin: 20px 0 8px 0; padding-bottom: 4px; border-bottom: 2px solid #e2e8f0; break-after: avoid; page-break-after: avoid; }
    h3 { font-size: 11pt; margin: 14px 0 4px 0; break-after: avoid; page-break-after: avoid; }
    p { margin: 0 0 8px 0; }
    table { width: 100%; border-collapse: collapse; margin: 0 0 8px 0; }
    thead { display: table-header-group; }
    tr { break-inside: avoid; page-break-inside: avoid; }
    th { background-color: #f1f5f9; color: #334155; font-size: 8pt; font-weight: 700; text-transform: uppercase; text-align: left; padding: 6px; border-bottom: 1px solid #cbd5e1; }
    td { padding: 6px; border-bottom: 1px solid #e2e8f0; vertical-align: top; overflow-wrap: anywhere; }
    .mx-num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
    .mx-nowrap { white-space: nowrap; }
    .mx-sub { display: block; font-size: 8.5pt; color: #475569; }
    .mx-nota { font-size: 9pt; color: #475569; }
    .mx-pie { margin-top: 24px; padding-top: 8px; border-top: 1px solid #e2e8f0; font-size: 8.5pt; color: #475569; break-inside: avoid; page-break-inside: avoid; }
  </style>
</head>
<body>
  <header class="mx-marca">
    <span class="mx-logo">MARGEN<span style="color: #6366f1;">X</span><span class="mx-lema">Control de rentabilidad en tiempo real</span></span>
    <span class="mx-chip">${escapeHtml(etiqueta)}</span>
  </header>
  <main>
    ${contenidoHtml}
  </main>
  <footer class="mx-pie">
    ${pieHtml ? `<p>${pieHtml}</p>` : ''}
    <p>MargenX &bull; Soporte: soporte@margenx.tech</p>
  </footer>
</body>
</html>`;
}
// </plantilla-mail-margenx>

const ZONA = 'America/Argentina/Buenos_Aires';
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Mismos nombres que la app: estados de la especificación funcional §6, unidades y motivos de cuarentena
const ESTADOS = { loss: 'Pérdida', risk: 'En riesgo' };
const UNIDADES = { kg: 'kg', g: 'g', l: 'litro', ml: 'ml', u: 'unidad', unit: 'unidad', unidad: 'unidad', litro: 'litro' };

const una = (texto) => String(texto ?? '').replace(/[\r\n]+/g, ' ').trim();
const unidad = (u) => UNIDADES[una(u).toLowerCase()] || una(u);
const esc = (texto) => escapeHtml(una(texto));
const variacion = (n) => `${Number(n) > 0 ? '+' : ''}${mxPorcentaje(n)}`;
const decimal = (n) => (Number(n) || 0).toLocaleString('es-AR', { maximumFractionDigits: 3 });
const seccion = (datos) => ({
  total: Number(datos?.totalCount) || 0,
  items: Array.isArray(datos?.items) ? datos.items : [],
});

function fecha(iso, conHora) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const opciones = { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: ZONA };
  if (conHora) Object.assign(opciones, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  return new Intl.DateTimeFormat('es-AR', opciones).format(d);
}

// AAAA-MM-DD en hora de Argentina, igual que el nombre del archivo de la descarga desde la app
function fechaArchivo(iso) {
  const partes = new Intl.DateTimeFormat('en-CA', { year: 'numeric', month: '2-digit', day: '2-digit', timeZone: ZONA }).formatToParts(new Date(iso));
  const parte = (tipo) => partes.find((p) => p.type === tipo).value;
  return `${parte('year')}-${parte('month')}-${parte('day')}`;
}

function motivoCuarentena(item) {
  if (item.quarantineReason === 'COSTO_UNITARIO_INSUFICIENTE') return 'Costo casi nulo';
  if (item.quarantineReason === 'VARIACION_MAYOR_50_POR_CIENTO') return Number(item.variationPercent) >= 0 ? 'Aumento > 50%' : 'Caída > 50%';
  return 'Variación anormal';
}

// Codifica en base64 sin Buffer ni btoa, que el nodo Code de n8n no garantiza
function aBase64(texto) {
  const utf8 = encodeURIComponent(texto);
  const bytes = [];
  for (let i = 0; i < utf8.length; i++) {
    if (utf8[i] === '%') {
      bytes.push(parseInt(utf8.substr(i + 1, 2), 16));
      i += 2;
    } else {
      bytes.push(utf8.charCodeAt(i));
    }
  }
  const ALFABETO = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let salida = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0);
    salida += ALFABETO[(n >> 18) & 63] + ALFABETO[(n >> 12) & 63];
    salida += i + 1 < bytes.length ? ALFABETO[(n >> 6) & 63] : '=';
    salida += i + 2 < bytes.length ? ALFABETO[n & 63] : '=';
  }
  return salida;
}

// num: monto alineado a la derecha; corto: texto que no se parte (la columna Estado, para que "Pérdida" no quede en dos líneas).
const claseColumna = (c) => (c.num ? ' class="mx-num"' : c.corto ? ' class="mx-nowrap"' : '');

function tabla(columnas, filas) {
  const th = columnas.map((c) => `<th${claseColumna(c)}>${escapeHtml(c.titulo)}</th>`).join('');
  const cuerpo = filas
    .map((fila) => `<tr>${fila.map((celda, i) => `<td${claseColumna(columnas[i])}>${celda}</td>`).join('')}</tr>`)
    .join('\n');
  return `<table>\n<thead><tr>${th}</tr></thead>\n<tbody>\n${cuerpo}\n</tbody>\n</table>`;
}

const sub = (texto) => `<span class="mx-sub">${texto}</span>`;
const nota = (texto) => `<p class="mx-nota">${texto}</p>`;
const resto = (datos, texto) =>
  datos.total > datos.items.length ? nota(`Se muestran ${mxEntero(datos.items.length)} de ${mxEntero(datos.total)}. ${texto}`) : '';

function validar(reporte) {
  if (!reporte || typeof reporte !== 'object') return 'El reporte llegó vacío.';
  if (!una(reporte.account?.businessName)) return 'El reporte no trae el nombre del comercio.';
  if (!reporte.catalogHealth || typeof reporte.catalogHealth !== 'object') return 'El reporte no trae la salud del catálogo.';
  if (Number.isNaN(new Date(reporte.generatedAt).getTime())) return 'El reporte no trae la fecha de generación.';
  return '';
}

function resumen(reporte) {
  const bajo = seccion(reporte.belowMinimumProducts);
  const cuarentena = seccion(reporte.quarantine);
  const viejos = seccion(reporte.staleCosts);
  return {
    comercio: una(reporte.account.businessName),
    desde: una(reporte.period?.fromFormatted) || fecha(reporte.period?.from),
    hasta: una(reporte.period?.toFormatted) || fecha(reporte.period?.to),
    bajo,
    cuarentena,
    viejos,
    dias: Number(reporte.staleCosts?.thresholdDays) || 30,
    cambios: seccion(reporte.weeklyCostChanges),
    ahorros: seccion(reporte.purchasingSavings),
    salud: reporte.catalogHealth,
    pendientes: bajo.total + cuarentena.total + viejos.total,
  };
}

function paraRevisar(d) {
  const partes = ['<h2>Para revisar</h2>'];
  if (d.pendientes === 0) {
    partes.push(mxAviso('ok', 'Nada para revisar esta semana', `<p style="margin: 0;">Ningún producto quedó debajo de su margen mínimo, no hay precios en cuarentena y todos los costos cambiaron en los últimos ${mxEntero(d.dias)} días.</p>`));
    return partes.join('\n');
  }
  if (d.bajo.total > 0) {
    partes.push(`<h3>Productos debajo de su margen mínimo (${mxEntero(d.bajo.total)})</h3>`);
    partes.push(nota('Del menor al mayor margen. El precio sugerido es el que devuelve a cada producto su margen mínimo.'));
    partes.push(tabla(
      [{ titulo: 'Producto' }, { titulo: 'Estado', corto: true }, { titulo: 'Margen', num: true }, { titulo: 'Precio actual', num: true }, { titulo: 'Precio sugerido', num: true }],
      d.bajo.items.map((p) => [
        esc(p.name),
        escapeHtml(ESTADOS[p.status] || ESTADOS.risk),
        `${escapeHtml(mxPorcentaje(p.marginPercent))}${sub(`mín. ${escapeHtml(mxPorcentaje(p.minMarginPercent))}`)}`,
        escapeHtml(mxPesos(p.salePrice)),
        `<strong>${escapeHtml(mxPesos(p.suggestedSalePrice))}</strong>`,
      ]),
    ));
    partes.push(resto(d.bajo, 'El resto está en la app, en Productos.'));
  }
  if (d.cuarentena.total > 0) {
    partes.push(`<h3>Precios en cuarentena (${mxEntero(d.cuarentena.total)})</h3>`);
    partes.push(nota('Precios de proveedores que MargenX frenó porque cambiaron demasiado. Se aceptan o se rechazan en Proveedores, Cuarentena.'));
    partes.push(tabla(
      [{ titulo: 'Insumo' }, { titulo: 'Proveedor' }, { titulo: 'Costo vigente', num: true }, { titulo: 'Costo propuesto', num: true }, { titulo: 'Variación', num: true }],
      d.cuarentena.items.map((q) => [
        `${esc(q.ingredientName)}${sub(escapeHtml(motivoCuarentena(q)))}`,
        esc(q.supplierName),
        `${escapeHtml(mxPesos(q.currentUnitCost))} / ${esc(unidad(q.unit))}${sub(`bulto: ${escapeHtml(mxPesos(q.currentPackagePrice))}`)}`,
        `${escapeHtml(mxPesos(q.proposedUnitCost))} / ${esc(unidad(q.unit))}${sub(`bulto: ${escapeHtml(mxPesos(q.pendingPackagePrice))}`)}`,
        escapeHtml(variacion(q.variationPercent)),
      ]),
    ));
    partes.push(resto(d.cuarentena, 'Se muestran los más antiguos; el resto está en la bandeja de la app.'));
  }
  if (d.viejos.total > 0) {
    partes.push(`<h3>Costos sin actualizar (${mxEntero(d.viejos.total)})</h3>`);
    partes.push(nota(`Insumos cuyo costo no cambia hace más de ${mxEntero(d.dias)} días. Conviene confirmarlo con el proveedor.`));
    partes.push(tabla(
      [{ titulo: 'Insumo' }, { titulo: 'Costo actual', num: true }, { titulo: 'Último cambio', num: true }, { titulo: 'Sin cambios', num: true }],
      d.viejos.items.map((s) => [
        esc(s.name),
        `${escapeHtml(mxPesos(s.currentCost))} / ${esc(unidad(s.unit))}`,
        escapeHtml(fecha(s.lastUpdatedAt)),
        escapeHtml(mxCantidad(s.daysWithoutUpdate, 'día', 'días')),
      ]),
    ));
    partes.push(resto(d.viejos, 'Se muestran los más antiguos.'));
  }
  return partes.filter(Boolean).join('\n');
}

function saludDelCatalogo(d) {
  const s = d.salud;
  const fila = (estado, cantidad, criterio) => [escapeHtml(estado), escapeHtml(mxEntero(cantidad)), escapeHtml(criterio)];
  return [
    '<h2>Salud del catálogo</h2>',
    `<p>${escapeHtml(mxCantidad(s.totalProducts, 'producto', 'productos'))} y ${escapeHtml(mxCantidad(s.activeIngredientsCount, 'insumo', 'insumos'))}. Margen promedio: <strong>${escapeHtml(mxPorcentaje(s.averageMarginPercent))}</strong> (la mediana de los productos con receta).</p>`,
    tabla(
      [{ titulo: 'Estado', corto: true }, { titulo: 'Productos', num: true }, { titulo: 'Criterio' }],
      [
        fila('Pérdida', s.lossCount, 'Margen menor a 0 %.'),
        fila('En riesgo', s.riskCount, 'Margen debajo del mínimo del producto.'),
        fila('En objetivo', s.targetCount, 'Margen entre el mínimo del producto y 60 %.'),
        fila('Superávit', s.surplusCount, 'Margen mayor a 60 %.'),
        fila('Borrador', s.draftCount, 'Sin receta: todavía no tiene margen.'),
      ],
    ),
  ].join('\n');
}

function cambiosDeCosto(d) {
  const partes = ['<h2>Cambios de costo de la semana</h2>'];
  if (d.cambios.total === 0) {
    partes.push('<p>No hubo cambios de costo en el período.</p>');
    return partes.join('\n');
  }
  partes.push(tabla(
    [{ titulo: 'Insumo' }, { titulo: 'Antes', num: true }, { titulo: 'Ahora', num: true }, { titulo: 'Variación', num: true }, { titulo: 'Productos', num: true }, { titulo: 'Fecha', num: true }],
    d.cambios.items.map((c) => [
      `${esc(c.ingredientName)}${sub(`por ${esc(unidad(c.unit))}`)}`,
      escapeHtml(mxPesos(c.oldCost)),
      escapeHtml(mxPesos(c.newCost)),
      escapeHtml(variacion(c.variationPercent)),
      escapeHtml(mxEntero(c.affectedProductsCount)),
      escapeHtml(fecha(c.changedAt)),
    ]),
  ));
  partes.push(resto(d.cambios, 'Se muestran los de mayor variación.'));
  return partes.filter(Boolean).join('\n');
}

function oportunidadesDeAhorro(d) {
  const partes = ['<h2>Oportunidades de ahorro</h2>'];
  if (d.ahorros.total === 0) {
    partes.push('<p>No hay presentaciones más baratas que las que usás hoy.</p>');
    return partes.join('\n');
  }
  partes.push(nota('Proveedores activos con una presentación más barata que la predeterminada, sin contar los precios en cuarentena.'));
  partes.push(tabla(
    [{ titulo: 'Insumo' }, { titulo: 'Hoy' }, { titulo: 'Más barato' }, { titulo: 'Ahorro por unidad', num: true }, { titulo: 'Ahorro por bulto', num: true }],
    d.ahorros.items.map((a) => [
      esc(a.ingredientName),
      `${esc(a.currentSupplierName)}${sub(`${escapeHtml(mxPesos(a.currentUnitCost))} / ${esc(unidad(a.unit))}`)}`,
      `${esc(a.bestSupplierName)}${sub(`${escapeHtml(mxPesos(a.bestUnitCost))} / ${esc(unidad(a.unit))}`)}`,
      `${escapeHtml(mxPesos(a.savingsPerUnit))}${sub(escapeHtml(mxPorcentaje(a.savingsPercent)))}`,
      `${escapeHtml(mxPesos(a.packageSavings))}${sub(`bulto de ${escapeHtml(decimal(a.packageSize))} ${esc(unidad(a.unit))}`)}`,
    ]),
  ));
  partes.push(resto(d.ahorros, 'El resto está en la app, en Compras.'));
  return partes.filter(Boolean).join('\n');
}

function documentoPdf(reporte, d) {
  const generado = reporte.generatedAt;
  const contenidoHtml = [
    `<h1>${escapeHtml(d.comercio)}</h1>`,
    `<p class="mx-nota">Reporte semanal de márgenes, del ${escapeHtml(d.desde)} al ${escapeHtml(d.hasta)}</p>`,
    paraRevisar(d),
    saludDelCatalogo(d),
    cambiosDeCosto(d),
    oportunidadesDeAhorro(d),
  ].join('\n');
  return mxDocumentoA4({
    titulo: `Reporte semanal de ${d.comercio}`,
    etiqueta: 'Reporte semanal',
    tono: d.pendientes > 0 ? 'aviso' : 'ok',
    contenidoHtml,
    pieHtml: `Generado el ${escapeHtml(fecha(generado, true))} (hora de Argentina). Montos calculados por MargenX al ${escapeHtml(fecha(generado))}.`,
  });
}

