    `<table width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse: collapse; border: 1px solid #e2e8f0; width: 100%; background-color: #ffffff;"><tbody>${filas}</tbody></table>`,
    `<p style="margin: 16px 0 0 0;">${escapeHtml(adjunto)}</p>`,
    `<p style="margin: 20px 0 0 0; text-align: center;">${mxBoton(enlace, 'Abrir MargenX')}</p>`,
  ].join('');
  const emailHtml = mxDocumento({
    titulo: `Reporte semanal de ${d.comercio}`,
    etiqueta: 'Reporte semanal',
    tono: d.pendientes > 0 ? 'aviso' : 'ok',
    contenidoHtml,
    pieHtml: `Comercio: <strong>${escapeHtml(d.comercio)}</strong>`,
  });
  const emailText = [
    `MargenX · Reporte semanal · ${d.comercio}`,
    periodo,
    '',
    `${titulo}:`,
    ...lineas.map((l) => `- ${l}`),
    '',
    ...numeros.map(([etiqueta, valor]) => `${etiqueta}: ${valor}`),
    '',
    adjunto,
    `Abrir MargenX: ${enlace}`,
    '',
    '---',
    'MargenX - Soporte: soporte@margenx.tech',
  ].join('\n');
  return { emailSubject: `MargenX · Reporte semanal · ${d.comercio}`, emailHtml, emailText };
}

