// Arma el aviso a Discord (canal de infraestructura) de una cuenta que no recibió su reporte: qué cuenta,
// en qué paso y con qué código HTTP. Sin correos ni datos personales. Modo: una vez por ítem.
const PASOS = {
  'Pedir Cuentas Activas': 'el backend no devolvió la lista de cuentas',
  'Pedir Reporte Semanal': 'el backend no devolvió el reporte',
  '¿Falló la descarga?': 'Gotenberg no generó el PDF',
  'Enviar Reporte (Brevo)': 'Brevo no aceptó el mail',
};

function cuenta() {
  try {
    return $('Separar Cuentas').item.json;
  } catch {
    return {};
  }
}

function codigoHttp(error) {
  if (!error) return '';
  const directo = typeof error === 'object' ? error.httpCode || error.statusCode || error.status : '';
  if (directo) return String(directo);
  const texto = typeof error === 'object' ? `${error.message || ''} ${error.description || ''}` : String(error);
  const hallado = /\b([45]\d\d)\b/.exec(texto);
  return hallado ? hallado[1] : '';
}

const item = $input.item.json;
const paso = $prevNode.name;
const datos = { ...cuenta(), ...(item.slug ? { slug: item.slug } : {}), ...(item.entorno ? { entorno: item.entorno } : {}) };
const entorno = datos.entorno || ($('Entorno Staging').isExecuted ? 'dev' : 'prod');
const etiqueta = entorno === 'dev' ? 'staging' : 'producción';
const codigo = codigoHttp(item.error);
const causa = item.motivo ? String(item.motivo).replace(/\.$/, '') : PASOS[paso] || `falló el paso "${paso}"`;
const http = codigo ? ` (HTTP ${codigo})` : '';

let content;
if (paso === 'Pedir Cuentas Activas') {
  const pista = ['401', '403'].includes(codigo) ? ' Revisar INTERNAL_WEBHOOK_SECRET en n8n y en el backend.' : '';
  content = `⚠️ [n8n · reporte semanal · ${etiqueta}] No se envió ningún reporte: ${causa}${http}.${pista}`;
} else {
  const slug = String(datos.slug || 'sin slug').replace(/[^a-z0-9-]/gi, '');
  content = `⚠️ [n8n · reporte semanal · ${etiqueta}] No se envió el reporte de "${slug}": ${causa}${http}. Las demás cuentas siguen.`;
}

return { json: { content } };
